    ylabel={$y$},
    zlabel={$z$},
    title={Surface: $xy = 1$ (Hyperbolic Cylinder)},
    view={45}{20},
    colormap/viridis,
    grid=major,
    domain=-2:2,
    y domain=-2:2,
    samples=50,
    unbounded coords=jump,
    restrict z to domain=-2:2,
    ]
